<?= $this->extend('layout') ?>
<?= $this->section('content') ?>
<?php $wh = (int) $so['warehouse_id']; $amt = 0; $open = false ?>
<div class="page-head"><div><h1>Order <?= esc($so['number']) ?> <?= badge($so['status']) ?></h1><p class="sub"><?= esc($so['customer']) ?><?= $so['customer_ref'] ? ' · their ref ' . esc($so['customer_ref']) : '' ?> · from <?= esc($so['wh']) ?></p></div>
<div class="actions"><?php if ($so['status'] === 'draft' && can('sales.manage', $wh)): ?><a class="btn secondary" href="<?= site_url('orders/' . $so['id'] . '/edit') ?>">Edit</a><form method="post" action="<?= site_url('orders/' . $so['id'] . '/confirm') ?>" class="inline"><?= csrf_field() ?><button class="btn" type="submit">Confirm</button></form><?php endif ?></div></div>
<section class="panel"><dl class="facts"><dt>Ordered</dt><dd><?= nice_date($so['order_date']) ?> by <?= esc($so['created_name']) ?></dd><?php if ($so['required_date']): ?><dt>Required by</dt><dd><?= nice_date($so['required_date']) ?></dd><?php endif ?>
<dt>Deliver to</dt><dd><?= esc($so['delivery_address'] ?: $so['town']) ?><?= $so['phone'] ? ' · ' . esc($so['phone']) : '' ?></dd><?php if ($so['notes']): ?><dt>Notes</dt><dd><?= nl2br(esc($so['notes'])) ?></dd><?php endif ?></dl></section>
<form method="post" action="<?= site_url('orders/' . $so['id'] . '/ship') ?>"><?= csrf_field() ?>
<div class="table-wrap"><table class="lines"><thead><tr><th>Item</th><th>Description</th><th class="num">Ordered</th><th class="num">Shipped</th><th class="num">Delivered</th><th class="num">Being prepared</th><th class="num">Free now</th><th class="num">Price</th><th class="num">Amount</th><?php if (in_array($so['status'], ['confirmed', 'in_progress'], true) && can('dispatch.manage', $wh)): ?><th>Ship now</th><?php endif ?></tr></thead><tbody>
<?php foreach ($lines as $l): $d = (int) $l['decimals']; $left = max(0, (float) $l['qty'] - (float) $l['qty_shipped'] - $l['on_ship']); $open = $open || $left > 0; $amt += (float) $l['qty'] * (float) $l['unit_price'] ?><tr>
<td class="mono"><?= esc($l['sku']) ?></td><td><?= esc($l['name']) ?></td><td class="num"><?= qty($l['qty'], $d) ?> <?= esc($l['uom']) ?><?= pack_hint($l['qty'], $l['pack_unit'], $l['pack_factor']) ?></td><td class="num"><?= qty($l['qty_shipped'], $d) ?></td><td class="num"><?= qty($l['qty_delivered'], $d) ?><?= (float) $l['qty_returned'] ? ' <span class="muted small">(' . qty($l['qty_returned'], $d) . ' back)</span>' : '' ?></td><td class="num"><?= $l['on_ship'] ? qty($l['on_ship'], $d) : '' ?></td>
<td class="num<?= $l['free'] < $left ? ' warn-text' : '' ?>"><?= qty($l['free'], $d) ?></td><td class="num"><?= money($l['unit_price'], false) ?></td><td class="num"><?= money((float) $l['qty'] * (float) $l['unit_price'], false) ?></td>
<?php if (in_array($so['status'], ['confirmed', 'in_progress'], true) && can('dispatch.manage', $wh)): ?><td><?php if ($left > 0): ?><input class="n" type="number" step="any" min="0" max="<?= $left ?>" name="qty[<?= $l['id'] ?>]" value="<?= min($left, $l['free']) ?>" aria-label="Quantity to ship"><?php endif ?></td><?php endif ?></tr><?php endforeach ?>
</tbody><tfoot><tr><td colspan="8">Total</td><td class="num"><?= money($amt) ?></td><?php if (in_array($so['status'], ['confirmed', 'in_progress'], true) && can('dispatch.manage', $wh)): ?><td></td><?php endif ?></tr></tfoot></table></div>
<?php if ($open && in_array($so['status'], ['confirmed', 'in_progress'], true) && can('dispatch.manage', $wh)): ?><div class="actions"><button class="btn" type="submit">Reserve stock and make a pick list</button><label class="check"><input type="checkbox" name="partial" value="1" checked> Ship what is free now; leave the rest on the order</label></div><?php endif ?>
</form>
<?php if ($shipments): ?><h2>Shipments</h2><div class="table-wrap"><table><thead><tr><th>Shipment</th><th>Status</th><th>Dispatched</th><th>Delivered</th><th>Received by</th></tr></thead><tbody>
<?php foreach ($shipments as $s): ?><tr><td><a href="<?= site_url('shipments/' . $s['id']) ?>"><?= esc($s['number']) ?></a></td><td><?= badge($s['status']) ?></td><td><?= local_time($s['dispatched_at']) ?></td><td><?= local_time($s['delivered_at']) ?></td><td><?= esc($s['pod_name']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if (! in_array($so['status'], ['delivered', 'closed', 'cancelled'], true) && can('sales.manage', $wh)): ?><details><summary>Cancel the order<?= $so['status'] === 'draft' || $so['status'] === 'confirmed' ? '' : ' (what has not been shipped)' ?></summary>
<form method="post" action="<?= site_url('orders/' . $so['id'] . '/cancel') ?>" class="inline-form"><?= csrf_field() ?><input name="why" placeholder="Why" required><button class="btn danger small" type="submit">Cancel order</button></form></details><?php endif ?>
<?= view('partials/activity', ['type' => 'sales_order', 'id' => $so['id']]) ?>
<?= $this->endSection() ?>
